import{_ as n,c as t,o as i}from"./chunks/framework.BGWP4WZ_.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"PY-XIAOZHI","tagline":"Framework điều khiển tương tác AI đa phương thức gọn nhẹ, đa nền tảng. Hỗ trợ giọng nói thời gian thực, nhận diện thị giác và điều khiển thiết bị IoT trên máy tính lẫn nền tảng nhúng ARM.","actions":[{"theme":"brand","text":"Bắt đầu ngay","link":"/vi/guide/文档目录"},{"theme":"alt","text":"Xem mã nguồn","link":"https://github.com/huangjunsen0406/py-xiaozhi"},{"theme":"alt","text":"Hướng dẫn phát triển","link":"/vi/guide/开发指南"}]},"features":[{"title":"Tương tác giọng nói AI","details":"Hỗ trợ thu âm và nhận diện giọng nói tự nhiên, mượt mà. Thiết kế bất đồng bộ (asyncio) giúp xử lý âm thanh thời gian thực với độ trễ thấp."},{"title":"Thị giác đa phương thức","details":"Hỗ trợ nhận diện và phân tích hình ảnh, mang lại khả năng tương tác đa phương thức. Tích hợp camera OpenCV và Pi CSI cho phân tích trực tiếp."},{"title":"Công cụ MCP & hệ sinh thái plugin","details":"Hệ thống công cụ mô-đun dựa trên JSON-RPC 2.0 với các công cụ âm lượng, ứng dụng, camera, chụp màn hình và thời tiết tích hợp sẵn; hỗ trợ cài plugin ZIP/thư mục ngoài ngay trong Cài đặt với tiến trình con cách ly."},{"title":"Nền tảng phát đa phương tiện độc lập","details":"Tách bạch hoàn toàn lớp âm thanh (AudioMixer + AudioDecoder) với MediaPlayer không phụ thuộc nguồn nhạc, tự động quản lý Audio Focus khi phát TTS; plugin âm thanh chỉ cần trả URL trực tiếp hoặc tệp cục bộ."},{"title":"Âm thanh độ trễ thấp & AEC tích hợp","details":"Chuỗi âm thanh thời gian thực dùng codec Opus và tái lấy mẫu SoXR, tích hợp sẵn khử tiếng vọng WebRTC APM trên cả 3 hệ điều hành, hỗ trợ hội thoại song công và ngắt lời tức thì."},{"title":"Đa nền tảng, đa giao diện & đa ngôn ngữ","details":"Hỗ trợ Windows 10+, macOS 10.15+ và Linux (kể cả Raspberry Pi) với 3 chế độ GUI (PySide6/QML), TUI (Textual), GPIO và chuyển đổi nóng tiếng Trung / Anh / Việt không cần khởi động lại."}]},"headers":[],"relativePath":"vi/index.md","filePath":"vi/index.md"}'),h={name:"vi/index.md"};function c(e,a,g,r,o,l){return i(),t("div")}const m=n(h,[["render",c]]);export{d as __pageData,m as default};
